import { useRef, useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import {
  getDeviceList,
  updateDeviceStatus,
  DeviceManagementTypes
} from '@/apis/admin/device-management'
import { getSysCommunityList } from '@/apis/admin/system-config'
import ExcelTable from '@/components/exportExcel'
import type { ExcelTableActionType } from '@/components/exportExcel'
import AreaCascader from '@/components/AreaCascader'
import { ProColumns } from '@ant-design/pro-components'
import {
  Button,
  Popconfirm,
  message,
  Tag,
  Progress,
  Tooltip,
  Badge,
  Space,
  Modal,
  Descriptions,
  QRCode,
  Alert
} from 'antd'
import {
  EyeOutlined,
  EditOutlined,
  ThunderboltOutlined,
  ExclamationCircleOutlined,
  QrcodeOutlined,
  StopOutlined,
  CheckCircleOutlined,
} from '@ant-design/icons'
import { ResultEnum } from '@/utils/enums/httpEnum'

// 设备状态映射
const deviceStatusMap: Record<number, { text: string; color: string }> = {
  1: { text: '在线', color: 'success' },
  2: { text: '离线', color: 'error' },
  3: { text: '故障', color: 'warning' },
  4: { text: '未激活', color: 'default' }
}

// 设备型号映射
const deviceModelMap: Record<string, { name: string; config: string }> = {
  望通: { name: '标准型A', config: '大5/中8/小20' },
  'ESP32-P4': { name: '标准型B', config: '大8/中5/小15' }
}

// 主柜类型映射
const cabinetTypeMap: Record<number, string> = {
  1: '标准型A',
  2: '标准型B',
  3: '标准型C'
}

const DeviceList: React.FC = () => {
  const actionRef = useRef<ExcelTableActionType>()
  const navigate = useNavigate()
  const [area, setArea] = useState<string[] | undefined>(undefined)
  const [communityOptions, setCommunityOptions] = useState<Record<string, { text: string }>>({})
  const [qrModalVisible, setQrModalVisible] = useState(false)
  const [qrDevice, setQrDevice] = useState<DeviceManagementTypes.DeviceListDto | null>(null)
  const [abnormalCount, setAbnormalCount] = useState(0)

  // 加载小区列表（根据省市区筛选）
  const loadCommunityList = async (provinceId?: number, cityId?: number, areaId?: number) => {
    try {
      const res = await getSysCommunityList({ provinceId, cityId, areaId })
      if (res.code === ResultEnum.SUCCESS && res.data?.list) {
        // 转换为 valueEnum 格式
        const options: Record<string, { text: string }> = {}
        res.data.list.forEach((item) => {
          options[item.id] = { text: item.communityName }
        })
        setCommunityOptions(options)
      }
    } catch (e) {
      console.error('获取小区列表失败:', e)
    }
  }

  // 筛选异常设备
  const filterAbnormalDevices = () => {
    // 设置表单值为故障状态
    actionRef.current?.setFieldsValue?.({ deviceStatus: '3' })
    // 提交表单并刷新
    actionRef.current?.submit?.()
  }

  // 获取异常设备数量（故障+离线）
  const fetchAbnormalCount = async () => {
    try {
      const [faultRes, offlineRes] = await Promise.all([
        getDeviceList({ page: 1, pageSize: 1, deviceStatus: 3 }),
        getDeviceList({ page: 1, pageSize: 1, deviceStatus: 2 })
      ])
      const faultCount = faultRes.code === ResultEnum.SUCCESS ? faultRes.data?.totalCount || 0 : 0
      const offlineCount = offlineRes.code === ResultEnum.SUCCESS ? offlineRes.data?.totalCount || 0 : 0
      setAbnormalCount(faultCount + offlineCount)
    } catch (e) {
      console.error('获取异常设备数量失败:', e)
    }
  }

  // 组件挂载时获取异常设备数量
  // useEffect(() => {
  //   fetchAbnormalCount()
  // }, [])

  // 查看设备详情
  const handleViewDetail = (record: DeviceManagementTypes.DeviceListDto) => {
    navigate(`/device/detail/${record.id}`)
  }

  // 编辑设备
  const handleEditDevice = (record: DeviceManagementTypes.DeviceListDto) => {
    navigate(`/device/edit/${record.id}`)
  }

  // 查看二维码
  const handleViewQrCode = (record: DeviceManagementTypes.DeviceListDto) => {
    setQrDevice(record)
    setQrModalVisible(true)
  }

  // 更新设备状态
  const handleUpdateStatus = async (
    record: DeviceManagementTypes.DeviceListDto,
    newStatus: number
  ) => {
    try {
      const res = await updateDeviceStatus(record.id, {
        deviceId: record.id,
        status: newStatus as 1 | 2
      })
      if (res.code === ResultEnum.SUCCESS) {
        message.success('状态更新成功')
        actionRef.current?.reload()
      } else {
        message.error('状态更新失败')
      }
    } catch (e) {
      console.error('更新设备状态失败:', e)
      message.error('状态更新失败')
    }
  }

  // 表格列定义
  const columns: ProColumns<DeviceManagementTypes.DeviceListDto>[] = [
    {
      title: '设备编号',
      dataIndex: 'imei',
      key: 'imei',
      width: 160,
      render: text => (
        <span style={{ fontFamily: 'Courier New, monospace', fontWeight: 500 }}>{text}</span>
      )
    },
    {
      title: '设备名称',
      dataIndex: 'deviceName',
      key: 'deviceName',
      width: 140
    },
    {
      title: '所属地区',
      dataIndex: 'areaName',
      key: 'areaName',
      hideInTable: true,
      valueType: 'cascader',
      renderFormItem: (_, { type, defaultRender, ...rest }) => (
        <AreaCascader
          name="area"
          placeholder="请选择所属地区"
          asyncMode={true}
          value={rest.value}
          onChange={(result) => {
            rest.onChange?.(result.labels)
            setArea(result.labels)
            // 根据省市区加载对应小区
            const ids = result.values || []
            const provinceId = ids[0] ? Number(ids[0]) : undefined
            const cityId = ids[1] ? Number(ids[1]) : undefined
            const areaId = ids[2] ? Number(ids[2]) : undefined
            loadCommunityList(provinceId, cityId, areaId)
            // 清空小区筛选
            actionRef.current?.setFieldsValue?.({ communityId: undefined })
          }}
        />
      )
    },
    {
      title: '所属地区',
      dataIndex: 'areaName',
      key: 'areaName_display',
      hideInSearch: true,
      width: 120,
      render: (_, record) => {
        // 直辖市特殊处理：只显示省级和区级（支持带"市"和不带"市"的格式）
        const municipalities = ['北京', '上海', '天津', '重庆']
        const municipalitiesWithShi = ['北京市', '上海市', '天津市', '重庆市']
        const isMunicipality = municipalities.includes(record.provinceName) || municipalitiesWithShi.includes(record.provinceName)
        const areaText = isMunicipality
          ? [record.provinceName, record.areaName].filter(Boolean).join(' / ')
          : [record.provinceName, record.cityName, record.areaName].filter(Boolean).join(' / ')
        return (
            <span>{areaText || '-'}</span>
        )
      }
    },
    {
      title: '小区',
      dataIndex: 'communityId',
      key: 'communityId',
      hideInTable: true,
      valueType: 'select',
      valueEnum: communityOptions,
      fieldProps: {
        disabled: !area || area.length === 0,
        placeholder: area && area.length > 0 ? '请选择小区' : '请先选择省市区'
      }
    },
    {
      title: '小区',
      dataIndex: 'communityName',
      key: 'communityName_display',
      hideInSearch: true,
      width: 120,
      render: text => text || '-'
    },
    {
      title: '设备位置',
      dataIndex: 'installLocation',
      key: 'installLocation',
      hideInSearch: true,
      width: 180,
      ellipsis: true
    },
    {
      title: '设备型号',
      dataIndex: 'deviceModel',
      key: 'deviceModel',
      width: 120,
      valueType: 'select',
      valueEnum: {
        '望通-W200': { text: '望通-W200' },
        '望通-W300': { text: '望通-W300' },
        'ESP32-E100': { text: 'ESP32-E100' }
      }
    },
    {
      title: '格口类型',
      dataIndex: 'mainCabinetType',
      key: 'mainCabinetType',
      hideInSearch: true,
      width: 180,
      render: (_, record) => {
        const model = deviceModelMap[record.deviceModel]
        return (
          <Space>
            <Tag color="blue">
              {model?.name || cabinetTypeMap[record.mainCabinetType] || '未知'}
            </Tag>
            <span style={{ fontSize: 12, color: '#999' }}>{model?.config || ''}</span>
          </Space>
        )
      }
    },
    {
      title: '在线状态',
      dataIndex: 'deviceStatus',
      key: 'deviceStatus',
      width: 100,
      align: 'center',
      valueType: 'select',
      valueEnum: {
        '1': { text: '在线', status: 'Success' },
        '2': { text: '离线', status: 'Error' },
        '3': { text: '故障', status: 'Warning' },
        '4': { text: '未激活', status: 'Default' }
      },
      render: (_, record) => {
        const status = deviceStatusMap[record.deviceStatus]
        return <Badge status={(status?.color as any) || 'default'} text={status?.text || '未知'} />
      }
    },
    {
      title: '格口使用率',
      dataIndex: 'status',
      key: 'occupancy',
      hideInSearch: true,
      width: 140,
      render: (_, record) => {
        // 模拟使用率，实际应从后端获取
        const occupancy = Math.floor(Math.random() * 100)
        const color = occupancy >= 80 ? '#ff4d4f' : occupancy >= 50 ? '#faad14' : '#52c41a'
        return (
          <Tooltip title={`使用率: ${occupancy}%`}>
            <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <Progress
                percent={occupancy}
                size="small"
                strokeColor={color}
                showInfo={false}
                style={{ flex: 1 }}
              />
              <span style={{ fontSize: 12, color, fontWeight: 500, minWidth: 35 }}>
                {occupancy}%
              </span>
            </div>
          </Tooltip>
        )
      }
    },
    {
      title: '激活时间',
      dataIndex: 'activeTime',
      key: 'activeTime',
      hideInSearch: true,
      width: 160,
      render: text => <span style={{ fontSize: 13, color: '#666' }}>{text || '-'}</span>
    },
    {
      title: '操作',
      key: 'option',
      valueType: 'option',
      fixed: 'right',
      width: 180,
      render: (_, record) => [
        <Tooltip title="查看二维码" key={`${record.id}-qrcode`}>
          <Button type="link" icon={<QrcodeOutlined />} onClick={() => handleViewQrCode(record)} />
        </Tooltip>,
        <Tooltip title="查看详情" key={`${record.id}-detail`}>
          <Button type="link" icon={<EyeOutlined />} onClick={() => handleViewDetail(record)} />
        </Tooltip>,
        <Tooltip title="编辑" key={`${record.id}-edit`}>
          <Button type="link" icon={<EditOutlined />} onClick={() => handleEditDevice(record)} />
        </Tooltip>,
        record.deviceStatus === 1 || record.deviceStatus === 3 ? (
          <Tooltip title="禁用" key={`${record.id}-disable`}>
            <Popconfirm
              title="确定要禁用该设备吗？"
              onConfirm={() => handleUpdateStatus(record, 2)}
              okText="确定"
              cancelText="取消"
            >
              <Button type="link" danger title="禁用" icon={<StopOutlined />} />
            </Popconfirm>
          </Tooltip>
        ) : record.deviceStatus === 2 ? (
          <Tooltip title="启用" key={`${record.id}-enable`}>
            <Popconfirm
              title="确定要启用该设备吗？"
              onConfirm={() => handleUpdateStatus(record, 1)}
              okText="确定"
              cancelText="取消"
            >
              <Button type="link" title="启用" icon={<CheckCircleOutlined />} style={{ color: '#52c41a' }} />
            </Popconfirm>
          </Tooltip>
        ) : null
      ]
    }
  ]

  return (
    <>
      {/* 告警提示 - 有异常设备时显示 */}
      {abnormalCount > 0 && (
        <Alert
          message={
            <Space>
              <span>当前有 <b>{abnormalCount}</b> 条设备异常告警，请及时处理</span>
              <Button
                size="small"
                danger
                ghost
                onClick={filterAbnormalDevices}
                icon={<ExclamationCircleOutlined />}
              >
                筛选异常设备
              </Button>
            </Space>
          }
          type="error"
          showIcon
          closable
          style={{ marginBottom: 16 }}
        />
      )}

      <ExcelTable
        key="device-list"
        columns={columns}
        requestFn={async params => {
          const { page, pageSize, imei, deviceModel, deviceStatus, ...rest } = params
          // 处理地区搜索参数
          let areaParams = {}
          if (area && Array.isArray(area) && area.length > 0) {
            if (area.length === 3) {
              // 三级结构：[省, 市, 区]
              areaParams = {
                province: area[0] || undefined,
                city: area[1] || undefined,
                district: area[2] || undefined
              }
            } else if (area.length === 2) {
              // 两级结构（直辖市）：[省, 区]
              areaParams = {
                province: area[0] || undefined,
                city: undefined,
                district: area[1] || undefined
              }
            } else if (area.length === 1) {
              // 只选择了省级
              areaParams = {
                province: area[0] || undefined,
                city: undefined,
                district: undefined
              }
            }
          }
          return await getDeviceList({
            page,
            pageSize,
            imei,
            deviceModel,
            deviceStatus,
            ...areaParams,
            ...rest
          })
        }}
        ref={actionRef}
        rowSelection={false}
        options={{
          fullScreen: false,
          reload: true,
          setting: false,
          density: false
        }}
        // toolBarRenderFn={() => [
        //   <Button
        //     key="activate"
        //     type="primary"
        //     icon={<ThunderboltOutlined />}
        //     onClick={handleActivateDevice}
        //   >
        //     激活设备
        //   </Button>
        // ]}
        scroll={{ x: 1400 }}
      />

      {/* 二维码弹窗 */}
      <Modal
        title={
          <Space>
            <QrcodeOutlined style={{ color: '#1890ff' }} />
            设备二维码
          </Space>
        }
        open={qrModalVisible}
        onCancel={() => setQrModalVisible(false)}
        footer={null}
        width={400}
        centered
      >
        {qrDevice && (
          <div style={{ textAlign: 'center', padding: '20px 0' }}>
            <div style={{ marginBottom: 16 }}>
              <div style={{ fontSize: 16, fontWeight: 600, marginBottom: 8 }}>
                {qrDevice.deviceName}
              </div>
              <div style={{ fontSize: 13, color: '#666' }}>设备编号：{qrDevice.imei}</div>
            </div>
            <div style={{ display: 'flex', justifyContent: 'center', marginBottom: 16 }}>
              {(() => {
                const QR_URL = `https://www.xilnk18.com/devices?imei=${qrDevice.imei}`
                return <QRCode value={QR_URL} size={200} level="H" bordered={false} />
              })()}
            </div>
            <div style={{ fontSize: 12, color: '#999' }}>扫描二维码查看设备详情</div>
          </div>
        )}
      </Modal>
    </>
  )
}

export default DeviceList
